parameters.jsCode:
const requiredLabels = [
  'Support',
  'Sales',
  'Information',
  'Other',
  'Spam/Newsletter',
  'Processed',
  'Error'
];

const existingLabels = $input.all();

const labelMap = {};

for (const item of existingLabels) {
  const { id, name } = item.json;

  if (id && name) {
    labelMap[name] = id;
  }
}

const missingLabels = requiredLabels.filter(
  name => !labelMap[name]
);

return [
  {
    json: {
      requiredLabels,
      labelMap,
      missingLabels,
      missingCount: missingLabels.length,
      allLabelsExist: missingLabels.length === 0
    }
  }
];
